SELECT event,description FROM system.events WHERE event IN ('UserTimeMicroseconds','SystemTimeMicroseconds','RealTimeMicroseconds','SelectedBytes','OSCPUWaitMicroseconds','OSIOWaitMicroseconds','QueryTimeMicroseconds','ReadCompressedBytes','CachedReadBufferReadFromCacheBytes','CachedReadBufferReadFromSourceBytes','QueryConditionCacheHits','QueryConditionCacheMisses','OSReadBytes') LIMIT 30 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames